package server
import("encoding/json";"net/http";"strings";"github.com/Ploos-AS/BotWeb/internal/pbmp";"github.com/Ploos-AS/BotWeb/internal/registry")
type Server struct{r registry.Registry}
func New(path string)(*Server,error){r,e:=registry.Load(path);return &Server{r:r},e}
func(s *Server)Handler()http.Handler{m:=http.NewServeMux();m.HandleFunc("GET /healthz",func(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","application/json");w.Write([]byte("{\"ok\":true}\n"))});m.HandleFunc("GET /api/v1/bots",s.bots);m.HandleFunc("GET /api/v1/bots/",s.bot);return m}
func(s *Server)bots(w http.ResponseWriter,_ *http.Request){type safe struct{ID string `json:"id"`;Name string `json:"name"`;Transport string `json:"transport"`};v:=make([]safe,0,len(s.r.Bots));for _,b:=range s.r.Bots{v=append(v,safe{b.ID,b.Name,b.Transport})};write(w,v)}
func(s *Server)bot(w http.ResponseWriter,r *http.Request){p:=strings.TrimPrefix(r.URL.Path,"/api/v1/bots/");parts:=strings.Split(strings.Trim(p,"/"),"/");if len(parts)!=2{http.NotFound(w,r);return};b,ok:=s.r.Find(parts[0]);if !ok||b.Transport!="unix"{http.NotFound(w,r);return};methods:=map[string]string{"info":"bot.info","capabilities":"capabilities.list","networks":"networks.list","protocol":"pbmp.info"};method,ok:=methods[parts[1]];if !ok{http.NotFound(w,r);return};v,e:=(pbmp.Client{Endpoint:b.Endpoint}).Call(method);if e!=nil{http.Error(w,e.Error(),http.StatusBadGateway);return};w.Header().Set("Content-Type","application/json");w.Write(v);w.Write([]byte("\n"))}
func write(w http.ResponseWriter,v any){w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(v)}
